theorem extend_partialOrder {α : Type u} (r : α → α → Prop) [IsPartialOrder α r] :
    ∃ s : α → α → Prop, IsLinearOrder α s ∧ r ≤ s  := by
  let S := { s | IsPartialOrder α s };
  have hS : ∀ c, c ⊆ S → IsChain (· ≤ ·) c → ∀ y ∈ c, ∃ ub ∈ S, ∀ z ∈ c, z ≤ ub   := by
    rintro c hc₁ hc₂ s hs;
    haveI := (hc₁ hs).1;
    refine ⟨sSup c, { refl := ?_, trans := ?_, antisymm := ?_ }, fun z hz => le_sSup hz⟩;
    refine
    exact { (λ x, ⟨s, hs, rfl x⟩), (λ x y _ ⟨s₁, h₁s₁, h₂s₁⟩ ⟨s₂, h₁s₂, h₂s₂⟩),
      cases (hc₂.total h₁s₁ h₁s₂) with h h,
      exact ⟨s₂, h₁s₂, _roots_.trans (h _ _ h₂s₁) h₂s₂⟩,
      exact ⟨s₁, h₁s₁, _roots_.trans h₂s₁ (h _ _ h₂s₂)⟩ }

problem imo2020_q2 (a b c d : ℝ) (hd0 : 0 < d) (hdc : d ≤ c) (hcb : c ≤ b) (hba : b ≤ a)
    (h1 : a + b + c + d = 1) : (a + 2 * b + 3 * c + 4 * d) * a ^ a * b ^ b * c ^ c * d ^ d < 1  := by
  have hp : a ^ a * b ^ b * c ^ c * d ^ d ≤ a * a + b * b + c * c + d * d
  calc _ ≤ (a + 2 * b + 3 * c + 4 * d) * (a * a + b * b + c * c + d * d) := by
    linear_combination hp + ((a + 2 * b + 3 * c + 4 * d) * (a * a + b * b + c * c + d * d)). ge
  _ ≤ _ := by linarith [show a ≤ 1 by linear_combination by apply_rules [sub_le_self]; simp [h1];
    show b ≤ 1 by linear_combination by apply_rules [sub_le_self]; simp [h1];
    show c ≤ 1 by linear_combination by apply_rules [sub_le_self]; simp [h1];
    show d ≤ 1 by linear_combination by apply_rules [sub_le_self]; simp [h1];]

theorem extend_partialOrder {α : Type u} (r : α → α → Prop) [IsPartialOrder α r] :
    ∃ s : α → α → Prop, IsLinearOrder α s ∧ r ≤ s   := by
  exact ⟨fun a b ↦ { s | IsPartialOrder α s ∧ IsTransitive r }

